eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   TWO_GIS_REVIEWS_URL: () => (/* binding */ TWO_GIS_REVIEWS_URL),\n/* harmony export */   reviews: () => (/* binding */ reviews)\n/* harmony export */ });\n/* harmony import */ var _review_details__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ./review-details */ \"(rsc)/./lib/review-details.ts\");\n\nconst TWO_GIS_REVIEWS_URL = \"https://2gis.ru/barnaul/firm/70000001082951397/tab/reviews\";\nconst baseReviews = [\n    {\n        id: \"261912592\",\n        author: \"Мака житель\",\n        date: \"27 июля 2026\",\n        isoDate: \"2026-07-27\",\n        rating: 5,\n        text: \"Очень нравится онлайн-запись и отношение к клиентам. Индивидуальный подход — это точно: даже если нет времени, можно связаться и на стрижку точно можно попасть.\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"256493999\",\n        author: \"Милана\",\n        date: \"8 июля 2026\",\n        isoDate: \"2026-07-08\",\n        rating: 5,\n        text: \"Очень понравился салон красоты RUTZ. Хороший индивидуальный подход. Покрасилась в рыжий с натурального цвета волос. Очень боялась, что волосы выпадут, но в итоге всё получилось красиво!\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"252975184\",\n        author: \"Svetlana Osipova\",\n        date: \"25 июня 2026\",\n        isoDate: \"2026-06-25\",\n        rating: 5,\n        text: \"От всей души благодарю мастера Дарью! Впервые за год я получила тот оттенок рыжего, который хотела. Мастер на предварительной консультации поняла меня буквально с полуслова, заранее объяснила все этапы окрашивания, а по завершении процедуры дала рекомендации по уходу. Были страхи, что, как и раньше после окрашивания у других мастеров, уйду расстроенная и придётся повторно идти исправлять, но тут результат превзошёл все мои ожидания, и я впервые вышла просто сияющая. Ходила раньше в этот салон на стрижки к мастеру Ксении, которая также с полуслова поняла, какое каре я хочу, поэтому уже больше полугода ходила только к ней. И как же я рада, что теперь нашла своего мастера по окрашиванию. Очень удобно, что записаться можно через приложение DIKIDI без звонков и подтверждений. Однозначно порекомендовала бы обоих мастеров.\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"252907841\",\n        author: \"Е Д\",\n        date: \"25 июня 2026\",\n        isoDate: \"2026-06-25\",\n        rating: 5,\n        text: \"Понравилось всё! От входа до конечного результата. Но, конечно, Дарья!!! Просто настоящий профи! Сделали полный уход и стрижку. В итоге — лучше, чем ожидала!\",\n        photos: [],\n        officialAnswer: {\n            date: \"25 июня 2026\",\n            text: \"Здравствуйте! Благодарю вас за отзыв \\uD83D\\uDE4F\"\n        },\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"243983007\",\n        author: \"Екатерина Поклонова\",\n        date: \"21 мая 2026\",\n        isoDate: \"2026-05-21\",\n        rating: 5,\n        text: \"Хочу выразить большую благодарность Дарье \\uD83C\\uDF39\\nСделали всё так, как я хотела: прекрасный уход, хорошее отношение, а самое главное — идеальная стрижка!\\nБоялась идти к парикмахеру, это был мой первый поход, было какое-то недоверие. С Дарьей было суперкомфортно, поэтому доверие появилось сразу. Не пожалела, что пошла именно к ней! Буду теперь только у неё наводить красоту \\uD83D\\uDE0A\\nВсё чисто, комфортно, прекрасная музыка на фоне. Советую теперь всем подругам.\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"242817820\",\n        author: \"Светлана Белорукова\",\n        date: \"16 мая 2026\",\n        isoDate: \"2026-05-16\",\n        rating: 5,\n        text: \"Хочу поделиться с вами: я сегодня по-настоящему вернула себя настоящую, ту самую нежную, игривую в глазах девушку благодаря Дарье и её пространству.\\nЯ была сегодня безумно счастлива побывать у тебя в гостях. Время пролетело незаметно, ты невероятная. Я доверилась тебе на все сто процентов и благодарна тебе за твой профессионализм ❤️❤️❤️\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"242759913\",\n        author: \"Татьяна Горохова\",\n        date: \"15 мая 2026\",\n        isoDate: \"2026-05-15\",\n        rating: 5,\n        text: \"То, что мне понравилась процедура, — это ничего не сказать. Но начнём сначала: в самом салоне приятно находиться, высокие потолки, достаточно большое пространство, эстетичный ремонт, выделенная зона ожидания. Удобная запись онлайн, без дополнительных звонков и разговоров — для меня это критично, потому что не всегда могу ответить на звонок.\\nЧувствуется индивидуальный и клиентоориентированный подход. Ничего лишнего не предлагалось, пока я сама не спросила про дополнительные услуги.\\nДарья сразу рассказала, что будет происходить за эти два часа процедуры: сначала помыли голову, сделали маску под термошапкой, далее была стрижка, потом ещё какие-то уходовые процедуры — я не запомнила \\uD83D\\uDE07 — и укладка.\\nДарья всегда комментировала свои действия, ответила на все мои многочисленные вопросы по уходу и окрашиванию. Два часа пролетели незаметно.\\nУ меня непростые, непослушные, натуральные кудрявые волосы: приручить их ой как непросто, напитать тоже. Но после процедуры мне постоянно хотелось их трогать, они были такие мягкие. Обычно укладки у меня не держатся совсем, но эта продержалась три дня, даже голову не хотелось мыть. Волосы блестят, выглядят здоровыми. Стрижка идеально подошла под кудрявый метод.\\nЯ столько лет не могла найти своего парикмахера — теперь нашла. Теперь только к Дарье.\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"242527390\",\n        author: \"светлана большакова\",\n        date: \"14 мая 2026\",\n        isoDate: \"2026-05-14\",\n        rating: 5,\n        text: \"Приходила на консультацию. Честно, боялась идти — думала, опять будут навязывать, говорить \\xabвам срочно надо\\xbb, шум, суета, придёшь уставшая и пожалеешь.\\nНо в RUTZ всё иначе. Дарья — это просто чудо. Девочки, кому нужна работа с сединой, — это к ней. Она знает все виды окрашивания, а её команда создаёт полный комфорт в пространстве красоты. Девочки, это просто находка для новичков.\\nЧто сделало визит особенным — тишина. Зашла и реально выдохнула. Никто не бегает, музыка не напрягает. Просто кайф.\\nЗапись без звонков — вообще любовь. Написал, договорился, пришёл. Без этих вечных \\xabалло, добрый день\\xbb. Мне так удобно.\\nИндивидуальный подход — это когда не переделывают под себя, а слушают. На консультации ответили на все мои \\xabа вдруг\\xbb спокойно и по делу.\\nВ общем, я боялась, а ушла довольная. Спасибо, что без спешки и по-человечески. Рекомендую, если устали от обычных салонов.\\nОтдельное спасибо мастеру Наталье: она сотворила чудо с моими волосами, всё прошло очень комфортно.\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"238585512\",\n        author: \"Альбина И\",\n        date: \"26 апреля 2026\",\n        isoDate: \"2026-04-26\",\n        rating: 5,\n        text: \"Не первый раз выбираю это пространство красоты для воплощения идей в макияже. Каждый раз это новый опыт, которым я остаюсь довольна.\\n\\nЗдесь учтут пожелания и подберут каждую деталь для гармоничного образа.\\n\\nДевушки создают уют и красоту своими руками, хочется возвращаться снова и снова.\",\n        photos: [],\n        officialAnswer: {\n            date: \"27 апреля 2026\",\n            text: \"Альбина, здравствуйте, благодарим вас за приятный отзыв \\uD83D\\uDD25 Ждём снова.\"\n        },\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"237830673\",\n        author: \"Дарья Гусева\",\n        date: \"23 апреля 2026\",\n        isoDate: \"2026-04-23\",\n        rating: 5,\n        text: \"Очень рада, что обратилась именно сюда! У меня натуральные, длинные волосы, и основная проблема в том, что они начинают сечься по мере роста. Дарья сделала мне идеальный ровный срез и экспресс-уход коллагеном. Я осталась безумно довольна, волосы очень мягкие, напитанные и плотные.\\nХочу ещё раз поблагодарить Дарью за то, что ответила на все мои вопросы по уходу и укладкам, дала рекомендации и всё очень подробно расписала \\uD83E\\uDD0D\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"237237497\",\n        author: \"Покровская усадьба22\",\n        date: \"20 апреля 2026\",\n        isoDate: \"2026-04-20\",\n        rating: 5,\n        text: \"Здравствуйте, хочу поделиться своим впечатлением о пространстве RUTZ.\\n\\nПо рекомендации записалась онлайн на консультацию в марте 2026 к Дарье. Кстати, онлайн очень удобно: спокойно, не торопясь, без дополнительных дозвонов и разговоров.\\n\\nБыла поставлена задача — решить вопрос с сединой на вьющихся, пористых волосах, при этом не краситься каждые две недели. Так как блонд мне категорически не идёт и качество волос на \\xab2\\xbb из \\xab10\\xbb \\uD83D\\uDE48, Дарья предложила матирование седины.\\n\\nПосле матирования Дарья подробно рассказала, как и чем правильно делать уходовые процедуры в домашних условиях.\\n\\nЯ довольна как слон. Волосы стали живыми! Я наконец-то вижу свои природные кудри, а не пух одуванчика.\\n\\nДарья, благодарю за индивидуальный подход. Теперь только к вам \\uD83E\\uDD70\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"237114629\",\n        author: \"Евгения Камардина\",\n        date: \"19 апреля 2026\",\n        isoDate: \"2026-04-19\",\n        rating: 5,\n        text: \"Профессионализм начинается с консультации!\\nХочу поблагодарить Дарью Рутц за невероятно грамотный подход! Для меня было важно не просто быстро подстричься или покраситься, а получить экспертное мнение.\\nОсобенно порадовала консультация: мастер не взялась сразу за ножницы или краску, а сначала подробно расспросила о моих привычках в уходе, образе жизни и пожеланиях. Мы разобрали мой тип волос, форму лица и даже то, сколько времени я готова тратить на укладку утром.\\nДарья доступно объяснила, почему одни варианты мне подойдут, а от других лучше отказаться, показала на схемах, как ляжет форма. В итоге мы выбрали идеальный вариант, и результат превзошёл ожидания!\\nОчень ценю, когда специалист отвечает за конечный результат и не боится уделить время разговору до начала процедуры. Такая консультация спасает от ошибок и разочарований. Спасибо за твой профессионализм и внимательное отношение!\",\n        photos: [],\n        officialAnswer: {\n            date: \"22 апреля 2026\",\n            text: \"Евгения, благодарю вам большое за доверие \\uD83D\\uDE0C Рады стараться ❤️\"\n        },\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"230060480\",\n        author: \"sorr1er\",\n        date: \"18 марта 2026\",\n        isoDate: \"2026-03-18\",\n        rating: 5,\n        text: \"Хочу выразить огромную благодарность профессионалу своего дела — Дарье. Моя ситуация была, так скажем, не из простых \\uD83E\\uDD72 После неудачного окрашивания я пришла именно к Дарье на консультацию. Очень круто, что такое вообще есть, потому что в других салонах мне даже отказывали в ней. Она всё подробно объяснила: как и почему такое произошло с волосами, и предложила разные варианты дальнейшей работы, чем и покорила моё доверие и сердечко ❤️‍\\uD83E\\uDE79 Я пять лет красилась в тотал-блонд, но каждый раз было сильное желание попробовать походить со своим цветом волос. Мне было важно, чтобы была возможность выйти обратно в блонд, так как был страх: \\xabа вдруг перетемнят, получится не мой цвет или просто не понравится\\xbb. И каждый раз мастера отговаривали, иногда не объясняя причины.\\n\\nДарья предложила просто идеальнейшую технику, о которой я узнала впервые именно от неё, — матирование. На окрашивании она подробно объясняла всё, что делает, каждый этап работы, рассказала, как ухаживать за волосами, и посоветовала средства, которые реально помогают. А волосы теперь живые и ухоженные. И самая главная философия Дарьи — индивидуальный подход, делать всё качественно и надолго, а не до первого мытья волос! В итоге получилось именно то, что я хотела — даже лучше! И никакого перехода не видно даже спустя месяц после окрашивания \\uD83E\\uDD7A\\nВ самой студии всегда царит дружеская атмосфера, все девочки приветливые и всегда предлагают чай, кофе и конфетки \\uD83D\\uDC95\\n\\nОбязательно вернусь к вам ещё и не раз, ведь результат превзошёл все ожидания \\uD83E\\uDD0D\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"218619752\",\n        author: \"Алиса Нузирова\",\n        date: \"11 февраля 2026\",\n        isoDate: \"2026-02-11\",\n        rating: 5,\n        text: \"Обожаю Дашу и её лёгкие ручки \\uD83E\\uDD70 Я знакома с ней как с мастером вот уже почти десять лет — всегда максимально учитывает пожелания, даёт рекомендации, знает индивидуальные особенности. У меня ух какой сложный волос: капризный, пористый, то стоит торчком, то распадается на сосульки и пеньки после стрижки кончиков, то сечётся, то агрессирует на уход. В общем, как хочет, так себя и ведёт \\uD83D\\uDE44 Далеко не каждый парикмахер стрижёт так, что после стрижки волосы выглядят лучше, чем было до!\\n\\nДаша же прекрасно учитывает индивидуальные особенности сложного волоса, находит нестандартные решения и управляется с прядками так, что потом они ведут себя воспитанно даже без укладки \\uD83D\\uDE01 Вымыл, высушил и пошёл.\\n\\nВ последние пару лет мы не совпадаем с Дашей по географии: я живу в центре, работа, малыш, сложный график. Долгая дорога — это критично. Всё никак не попадаю к любимому мастеру. Стриглась у местных, нашла хорошего, но длину не доверишь — бывает, что неточно слышит пожелания и на свой вкус хорошенько отстригает.\\n\\nА тут я решила отращивать длину снова — и это только к Даше! Она как никто умеет убрать на кончиках самый минимальный минимум так, что причёска становится опрятной и обновлённой, а длина при этом остаётся на месте. Прядки не распадаются при этом пеньками, ложатся красиво, а обновлённая причёска держит форму ещё несколько месяцев. Обалдеть же. Мечта!\\n\\nВ общем, очень рада была снова оказаться в Дашиных чудесных профессиональных ручках, но в новом для меня месте. Всё как всегда: комфортно, всё объясняет, уточняет каждое пожелание. Индивидуальный подход — это не пустые красивые слова, а в случае с моими капризными волосами и их постоянными причудами — реальная необходимость! Сам салон уютный, удобный.\\n\\nСпасибо!\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"216427484\",\n        author: \"Полина Морозова\",\n        date: \"3 февраля 2026\",\n        isoDate: \"2026-02-03\",\n        rating: 5,\n        text: \"Я хожу на стрижку к мастеру Дарье раз в 5–6 месяцев, когда чувствую, что волосы отросли или секутся кончики. Получаю комплименты, что мои волосы отлично лежат даже без укладки и сами подкручиваются. Но я-то знаю, что это результат тщательной и кропотливой работы мастера.\\n\\nМне очень нравится то, как Дарья подходит к своей работе и к клиентам. Она не только делает \\xabтак, как хочет клиент\\xbb, но и даёт рекомендации по стрижке. Для меня это важно: чтобы меня не просто подстригли по моему желанию, а с экспертной точки зрения скорректировали мои \\xabхотелки\\xbb. Мастер всегда скажет, нужен или нет уход волосам. Она не рекламирует продукты ради продажи, а говорит именно о состоянии моих волос, не навязывая дополнительные услуги, а я ценю честность.\\n\\nОтдельно хочу отметить студию. Мне нравятся интерьер и музыка внутри — нет толпы народа, и создаётся ощущение персональной консультации. Также очень удобно время записи: я работаю 5/2, и для меня большая проблема приходить в будни, поэтому наличие окон в выходные дни — огромный плюс.\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"211149398\",\n        author: \"Анжелика Вислогузова\",\n        date: \"9 января 2026\",\n        isoDate: \"2026-01-09\",\n        rating: 5,\n        text: \"Хочу поблагодарить мастеров пространства красоты RUTZ. Даша, спасибо за отличное матирование волос. Всё прошло замечательно:\\n\\nвнимательно выслушали пожелания;\\n\\nчётко поняли задачу;\\n\\nвыполнили работу аккуратно и профессионально.\\n\\nРезультат превзошёл ожидания — волосы выглядят именно так, как я хотела. Спасибо!\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    },\n    {\n        id: \"211103369\",\n        author: \"Наталья Лаврова\",\n        date: \"9 января 2026\",\n        isoDate: \"2026-01-09\",\n        rating: 5,\n        text: \"Хочу оставить свой отзыв о пространстве красоты RUTZ.\\nЯ посещаю данный салон не только за красотой, но ещё и за общением. Атмосфера здесь всегда комфортная и уютная.\\nЯ пришла со своей проблемой — частое окрашивание отросших седых волос. Мне необходим был камуфляж седины.\\nРабота была проделана колоссальная, трудоёмкая и по времени заняла десять часов.\\nРезультат превзошёл все мои ожидания. Я, конечно, предполагала, что мастера Даша и Наташа — волшебницы...\\nИ вот что получилось...\",\n        photos: [],\n        sourceUrl: TWO_GIS_REVIEWS_URL\n    }\n];\nconst reviews = baseReviews.map((review)=>({\n        ...review,\n        photos: (_review_details__WEBPACK_IMPORTED_MODULE_0__.reviewDetails[review.id]?.photos ?? review.photos).map((photo, index)=>({\n                ...photo,\n                alt: `Фото к отзыву ${review.author}, ${index + 1}`\n            })),\n        officialAnswer: _review_details__WEBPACK_IMPORTED_MODULE_0__.reviewDetails[review.id]?.officialAnswer ?? review.officialAnswer\n    }));\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./lib/reviews.ts\n");

